      const raw = await c.env.TOKEN_APP_KV.get(KV_KEYS.TASK_SPEND);
      if (!raw) return c.json({ error: 'Task spend not yet available' }, 404);
      return c.body(raw, 200, { 'Content-Type': 'application/json' });
