// ── Provider pages ────────────────────────────────────────────────────────────

async function handleProviderPage(c: any, providerId: string) {
  try {
    const { models } = await getModels(c.env);
    // Compare CANONICAL ids on both sides. KV holds normalized models written by the
    // previous deploy, so between a rename shipping and the next refresh a model's
    // stored providerId is still the retired spelling; a raw `===` would render an
    // empty provider page for the whole vendor and nothing would report an error.
    const want = canonicalProviderId(providerId);
    const filtered = models.filter((m: any) => canonicalProviderId(m.providerId) === want);
    const html = getProviderHtml({ providerId: want, models: filtered });
    return c.html(html, 200, {
      'Cache-Control': 'public, max-age=300, stale-while-revalidate=3600',
    });
  } catch (err) {
    console.error('Provider page failed:', err);
    return c.redirect('/', 302);
  }
}

for (const slug of PROVIDER_SLUGS) {
  app.get(`/${slug}`, (c) => handleProviderPage(c, slug));
}

// Retired provider slugs keep resolving. `/x-ai` is in the live sitemap and carries
// inbound links, so it 301s to the current page rather than 404ing or being quietly
// dropped — the slug is OpenRouter's namespace, not something we get to revoke.
for (const [from, to] of Object.entries(PROVIDER_SLUG_REDIRECTS)) {
  app.get(`/${from}`, (c) => c.redirect(`/${to}`, 301));
}

// ── Model detail + comparison pages ──────────────────────────────────────────
// SSR, cached at the edge for an hour. These are the programmatic SEO surface:
// llm-stats' equivalent "X vs Y" pages are its main organic engine, and the
// SUBSCRIPTION half of ours is uncontested — they are API-only and cannot answer
// "ChatGPT Plus vs Claude Pro" at all.

app.get('/model/:slug', async (c) => {
  try {
    const slug = c.req.param('slug');
    const [{ models }, benchmarks, subs] = await Promise.all([
      getModels(c.env),
      readBenchmarks(c.env),
      getSubscriptions(c.env),
    ]);
    const model = models.find((m) => m.slug === slug);
    if (!model) return c.redirect('/', 302);
    // Per-host prices are fetched lazily (read-through KV, 6h TTL) because we
    // can't afford 338 endpoint calls per cron. getModelEndpoints() already
    // swallows its own failures and returns null → the panel is simply omitted,
    // so a slow upstream can't block the page.
    // Usage history comes from our own accumulated D1 snapshots. Like the
    // endpoints call it swallows its own failures and returns null → the panel is
    // omitted, so neither a D1 blip nor a model that has never charted can break
    // the page. Both are independent of each other, so they run together.
    const [endpoints, usage] = await Promise.all([
      getModelEndpoints(c.env, model.id),
      readModelUsage(c.env, model.id),
    ]);
    return c.html(getModelHtml({ model, all: models, benchmarks, subscriptions: subs, endpoints, usage }), 200, {
      'Cache-Control': 'public, max-age=3600, stale-while-revalidate=86400',
    });
  } catch (err) {
    console.error('Model page failed:', err);
    return c.redirect('/', 302);
  }
});

/**
 * Split "a-vs-b" into its two halves.
 *
 * Naively splitting on the FIRST "-vs-" is wrong: model slugs are hyphen-heavy
 * and nothing stops one containing the literal substring. So try every split
 * point and accept the first where BOTH halves resolve — resolution is the
 * disambiguator, not string position.
 */
function splitPair<T>(pair: string, resolve: (s: string) => T | undefined): [T, T] | null {
  const SEP = '-vs-';
  let i = pair.indexOf(SEP);
  while (i !== -1) {
    const a = resolve(pair.slice(0, i));
    const b = resolve(pair.slice(i + SEP.length));
    if (a && b) return [a, b];
    i = pair.indexOf(SEP, i + 1);
  }
  return null;
}

app.get('/compare/:pair', async (c) => {
  try {
    const pair = c.req.param('pair');
    const [{ models }, subs, benchmarks] = await Promise.all([
      getModels(c.env),
      getSubscriptions(c.env),
      readBenchmarks(c.env),
    ]);

    // Subscriptions first: their ids are the higher-intent, higher-volume queries
    // ("chatgpt-vs-claude-ai"). Verified today: zero overlap between the 28
    // subscription ids and all 338 model slugs, so precedence is not lossy.
    const subPair = splitPair(pair, (s) => subs.find((x: Subscription) => x.id === s));
    if (subPair) {
      return c.html(getSubCompareHtml({ a: subPair[0], b: subPair[1], all: subs }), 200, {
        'Cache-Control': 'public, max-age=3600, stale-while-revalidate=86400',
      });
    }

    const modelPair = splitPair(pair, (s) => models.find((x) => x.slug === s));
    if (modelPair) {
      return c.html(getModelCompareHtml({ a: modelPair[0], b: modelPair[1], all: models, benchmarks }), 200, {
        'Cache-Control': 'public, max-age=3600, stale-while-revalidate=86400',
      });
    }

    return c.redirect('/', 302);
  } catch (err) {
    console.error('Compare page failed:', err);
    return c.redirect('/', 302);
  }
});

