app.get('/', async (c) => {
  try {
    // Server-side render with initial data (avoids client-side waterfall)
    const [{ models, lastUpdated }, subs, rankings, benchmarks] = await Promise.all([
      getModels(c.env),
      getSubscriptions(c.env),
      getRankings(c.env),
      readBenchmarks(c.env),
    ]);

    const html = getHtml({
      initialModels: JSON.stringify(models),
      initialSubscriptions: JSON.stringify(subs),
      initialRankings: rankings ? JSON.stringify(rankings) : 'null',
      initialBenchmarks: benchmarks ? JSON.stringify(benchmarks) : 'null',
      lastUpdated,
    });

    return c.html(html, 200, {
      'Cache-Control': 'public, max-age=60, stale-while-revalidate=300',
    });
  } catch (err) {
    // Fallback: serve shell without initial data, client fetches it
    console.error('SSR failed, serving shell:', err);
    const html = getHtml({});
    return c.html(html, 200, {
      'Cache-Control': 'public, max-age=30',
    });
  }
});

// ── Cloudflare Worker Export ──────────────────────────────────────────────────

export default {
  // Fetch handler (HTTP requests)
  fetch: app.fetch,

  // Scheduled handler (Cron Trigger — runs every hour)
  async scheduled(
    _event: ScheduledEvent,
    env: Env,
    ctx: ExecutionContext
  ): Promise<void> {
    ctx.waitUntil(
      refreshAllData(env, { includeCategories: true }).then((result) => {
        console.log(`[cron] Refreshed: ${result.models} models, categories: ${result.categories ?? 'n/a'}`);
      }).catch((err) => {
        console.error('[cron] Refresh failed:', err);
      })
    );
  },
};
